	[1420] = {
		["agamand family crypt"] = {
			name = "Agamand Family Crypt",
			short = "The Agamand Family Crypt is located just north of Agamand Mills in northern Tirisfal Glades.",
			full = "The Agamand Family Crypt is located just north of Agamand Mills in northern Tirisfal Glades. Captain Dargol, a minion of the Scourge, has settled here and awakened all the corpses and spirits of the Agamands' dead ancestors. It is a dark and dusty place, and the vengeful undead attack anyone who enter unbidden.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Family_Crypt",
		},
		["agamand mills"] = {
			name = "Agamand Mills",
			short = "The Agamand Mills is a vast windmill network in the highlands of northern Tirisfal Glades.",
			full = "The Agamand Mills is a vast windmill network in the highlands of northern Tirisfal Glades. Once owned by the wealthy Agamand family, the area was taken over by the undead and is now probably the largest Scourge outpost in Tirisfal. It can be accessed from the west by a road leading up from Calston Estate, and from the east by a road from Garren's Haunt.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Mills",
		},
		["balnir farmstead"] = {
			name = "Balnir Farmstead",
			short = "The Balnir Farmstead is a ruined farm in eastern Tirisfal Glades, northeast of the Ruins of Lordaeron.",
			full = "The Balnir Farmstead is a ruined farm in eastern Tirisfal Glades, northeast of the Ruins of Lordaeron. It was the home of the Balnir family, who bred the famous white horses of Lordaeron (most famously Arthas Menethil's Invincible and Anduin Wrynn's Reverence), but is now inhabited only by a few roaming Scourge. The farm's most notable feature is the grave of Invincible, left empty since Arthas resurrected the horse during the Third War.",
			source = "https://warcraft.wiki.gg/wiki/Balnir_Farmstead",
		},
		["brightwater lake"] = {
			name = "Brightwater Lake",
			short = "Brightwater Lake is the biggest lake in Tirisfal Glades, located just northeast of Brill, south of the North Coast, and west of the Scarlet Watch Post.",
			full = "Brightwater Lake is the biggest lake in Tirisfal Glades, located just northeast of Brill, south of the North Coast, and west of the Scarlet Watch Post. Gunther's Retreat is situated on a large island in the center.\n\n2,600 BDP, Eidre and her family owned the land around a keep near the lake. The dreadlord Kathra'natir infected the area. The first Guardian of Tirisfal, Alodi, battled the demon on a small island here.\n\nBrightwater's entire western shore was scorched by the Lion's Wake during the Battle for Lordaeron, but the water itself and the islands on it were unaffected.",
			source = "https://warcraft.wiki.gg/wiki/Brightwater_Lake",
		},
		["brill"] = {
			name = "Brill",
			short = "Brill is a small town under the control of the Forsaken, in the Tirisfal Glades of northern Lordaeron.",
			full = "Brill is a small town under the control of the Forsaken, in the Tirisfal Glades of northern Lordaeron. Upon leaving Deathknell, new Forsaken adventurers will be directed to Brill where they will continue the Forsaken's war against both the Scarlet Crusade and the ever-present Scourge. It is located in the center of Tirisfal, directly north of the Ruins of Capital City.\n\nAfter the Battle for Lordaeron, not much was left of the town but rubble and ruins. Sometime after the war against the Jailer, the Forsaken regained control of the town and began its reconstruction.",
			source = "https://warcraft.wiki.gg/wiki/Brill",
		},
		["brill town hall"] = {
			name = "Brill Town Hall",
			short = "The Brill Town Hall was the most prominent structure in the town of Brill in central Tirisfal Glades. Magistrate Sevren led the town from his podium, issuing orders and tasks to willing Forsaken subjects.",
			full = "The Brill Town Hall was the most prominent structure in the town of Brill in central Tirisfal Glades. Magistrate Sevren led the town from his podium, issuing orders and tasks to willing Forsaken subjects. The town hall was also notable because it was the only town hall in the realms known to be run by the Forsaken besides the Defiler's Den.",
			source = "https://warcraft.wiki.gg/wiki/Brill_Town_Hall",
		},
		["bulwark"] = {
			name = "Bulwark",
			short = "The Bulwark is the Forsaken's last bastion of defense against the forces of the Scourge to the east, located on the border of Tirisfal Glades and the Western Plaguelands.",
			full = "The Bulwark is the Forsaken's last bastion of defense against the forces of the Scourge to the east, located on the border of Tirisfal Glades and the Western Plaguelands. The Argent Dawn and Forsaken defenders at the Bulwark have teamed up to protect the land from the hordes of undead to the east, and send experienced adventurers of the Horde to battle the minions of the Lich King.\n\nUnlike the rest of Tirisfal Glades, this area was filled with plaguemist until recently, the sky tinted the same yellowish-gray color as in the Western Plaguelands. However, with the reclamation efforts underway in the Plaguelands, this effect has subsided and the area looks like the rest of Tirisfal.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["calston estate"] = {
			name = "Calston Estate",
			short = "Calston Estate is a new Horde quest hub in Tirisfal Glades, complete with Forsaken-themed architecture, located west of Stillwater Pond.",
			full = "Calston Estate is a new Horde quest hub in Tirisfal Glades, complete with Forsaken-themed architecture, located west of Stillwater Pond. It contains profession and class trainers so players will not need to run back and forth between here and Brill. The estate is owned by the lonely Sedrick Calston.\n\nFrom here the Forsaken launch attacks on the Solliden Farmstead, perform experiments along the Tirisfal coast, etc.\n\nSome Scarlet Crusade propaganda pamphlets were distributed near the estate, accusing Anduin of conspiring with his secret lover Sylvanas at the Gathering of the Arathi Highlands in order to kill Calia Menethil and make secure his claims to the kingdom, and further claiming to have Calia's surviving son as the last remaining heir to the Menethil dynasty, with whom the Brotherhood intended to one day end Anduin's \"puppet reign\".",
			source = "https://warcraft.wiki.gg/wiki/Calston_Estate",
		},
		["cold hearth manor"] = {
			name = "Cold Hearth Manor",
			short = "Cold Hearth Manor is a farmstead in central Tirisfal Glades, formerly known for its warm atmosphere and bountiful crops.",
			full = "Cold Hearth Manor is a farmstead in central Tirisfal Glades, formerly known for its warm atmosphere and bountiful crops. After the Plague of Undeath claimed the lives of everyone who lived or worked here, the fields have grown barren and become infested with mindless Scourge zombies.\n\nThe Forsaken managed to claim the farmhouse for themselves. They now offer trade opportunities to travelers passing on the main road nearby.\n\nAfter the Forsaken reclaimed Brill, Tirisfal Farmers took control of the manor, and Scarlet Warriors patroled the road in front of it.",
			source = "https://warcraft.wiki.gg/wiki/Cold_Hearth_Manor",
		},
		["crusader outpost"] = {
			name = "Crusader Outpost",
			short = "Crusader Outpost is a scout tower located in eastern Tirisfal Glades.",
			full = "Crusader Outpost is a scout tower located in eastern Tirisfal Glades. It is under the control of the Scarlet Crusade, who use it to keep an eye on the main road through the glades south of the hills the tower has been built on, and also to provide for flanking opportunities against enemies who try to assault the Scarlet Monastery. This particular tower is commanded by Captain Vachon. There's evidence of an attack here from Lilian Voss.",
			source = "https://warcraft.wiki.gg/wiki/Crusader_Outpost",
		},
		["crusaders outpost"] = {
			name = "Crusader's Outpost",
			short = "This Crusader's Outpost is a scout tower located within the Scarlet Palisade of western Tirisfal Glades.",
			full = "This Crusader's Outpost is a scout tower located within the Scarlet Palisade of western Tirisfal Glades. It is under the control of the Scarlet Crusade, who have allied with the farmers of Solliden Farmstead in order to fight back the Scourge and Forsaken who have settlements nearby. This tower is the westernmost holding of the Scarlet Crusade in all of Lordaeron, which also means they are so far from their main base of Tyr's Hand that should any trouble befall them, they will not have enough time to wait for reinforcements. It is one of the four Crusader's Outpost towers in Tirisfal Glades.\n\nIt's here the Scarlet Crusade brought Lilian Voss as a prisoner, awaiting word back from her father for her fate.",
			source = "https://warcraft.wiki.gg/wiki/Crusader's_Outpost",
		},
		["darkwalk"] = {
			name = "Darkwalk",
			short = "The Darkwalk is an underground and partially collapsed passage found within the Tomb of Tyr that leads from the proper tomb chamber to the Grave-Prison of Zakajz.",
			full = "The Darkwalk is an underground and partially collapsed passage found within the Tomb of Tyr that leads from the proper tomb chamber to the Grave-Prison of Zakajz.\n\nDuring the third invasion of the Burning Legion, the tomb was breached by the Argent Crusade with Tyr's Guard, priests of the Conclave, and Valarjar warriors sent by Odyn, they passed through the Darkwalk, defeating the Twilight's Hammer and Old Gods' forces.\n\nYears later, Travard entered the Tomb again, this time with Watcher Koranos. When they escaped to the Darkwalk, they found a Damaged Titan Matrix, guarded by two Silver Golems, and a Titan Transporter.",
			source = "https://warcraft.wiki.gg/wiki/Darkwalk",
		},
		["deathknell"] = {
			name = "Deathknell",
			short = "Deathknell is a small Forsaken village nestled in a well-guarded valley just north of Silverpine Forest in Tirisfal Glades which serves as the starting area for the Forsaken.",
			full = "Deathknell is a small Forsaken village nestled in a well-guarded valley just north of Silverpine Forest in Tirisfal Glades which serves as the starting area for the Forsaken. One of the greatest struggles for the citizens of Deathknell is obtaining the natural resources they need to survive, particularly gold. The gold mine to the northwest has been overrun by spiders, and the people of Deathknell frequently attempt to clear it out, so that they may begin mining its precious metals. In the meantime, they do what they must to survive in the face of the Scourge and the Scarlet Crusade.\n\nLore-wise, Deathknell is unique among Forsaken sites due to its name. While other communities inhabited by the rebel undead of the Banshee Queen retained their names from their days as centers of human civilization, Deathknell was obviously renamed to its current appellation for reasons unknown. The valley itself is guarded by a number of Deathguard Elites.",
			source = "https://warcraft.wiki.gg/wiki/Deathknell",
		},
		["deathknell graves"] = {
			name = "Deathknell Graves",
			short = "The Deathknell Graves is a mass grave outside the Shadow Grave in Deathknell. All undead player characters start here, waiting to be \"resurrected\" by their first quest, given by the val'kyr Agatha.",
			full = "The Deathknell Graves is a mass grave outside the Shadow Grave in Deathknell. All undead player characters start here, waiting to be \"resurrected\" by their first quest, given by the val'kyr Agatha. A grave marker next to the player reads, \"Corpse of <player name>\".\n\nIn addition to Agatha, two other val'kyr, Arthura and Aradne, are present as well. Arthura will patrol the area while Aradne goes about attempting to resurrect the Risen Dead in a periodic scripted event with mixed results.\n\nUpon approaching a corpse, Aradne will say something such as, \"Rise from the grave and serve the Dark Lady!\" While the Risen Dead often either embrace their fate or at least resign themselves to it and seek assistance from Undertaker Mordo, they will sometimes react similarly to Lilian Voss and declare, \"I should be dead and to death I will return!\" They will then perform a death animation. They also occasionally say, \"I never asked for this! Leave me alone!\" after which they perform an enrage animation and become one of the Mindless Zombies who wander the area.\n\nOther recent arrivals from death include Darnell, an companion NPC similar to Zuni who follows the player. Additionally, Caretaker Caice sends players to introduce Voss, Marshal Redpath and Valdred Moray to their new lives.",
			source = "https://warcraft.wiki.gg/wiki/Deathknell_Graves",
		},
		["deaths watch waystation"] = {
			name = "Death's Watch Waystation",
			short = "Death's Watch Waystation was a small camp just southeast of Brill in the Tirisfal Glades. It was a Deathguard waystation.",
			full = "Death's Watch Waystation was a small camp just southeast of Brill in the Tirisfal Glades. It was a Deathguard waystation.\n\nDuring the events of the Battle for Lordaeron, the waystation had been already destroyed and there was no trace of it.\n\nWhen the Forsaken reclaimed Brill, they used the area of the Waystation as a staging ground for the deployment of the Plague Eater against the remaining blight in Tirisfal.",
			source = "https://warcraft.wiki.gg/wiki/Death's_Watch_Waystation",
		},
		["faols rest"] = {
			name = "Faol's Rest",
			short = "Faol's Rest is located in eastern Tirisfal Glades, just southwest of the Scarlet Monastery. It serves as the graveyard for those dying in Scarlet Monastery or low-level quests around that place.",
			full = "Faol's Rest is located in eastern Tirisfal Glades, just southwest of the Scarlet Monastery. It serves as the graveyard for those dying in Scarlet Monastery or low-level quests around that place.",
