		["gallows end tavern"] = {
			name = "Gallows' End Tavern",
			short = "Gallows' End Tavern is an inn located in Brill in the Tirisfal Glades. It features trainers for warriors, priests, mages, rogues, warlocks, enchanters, and first aid, in addition to the innkeeper and a few other vendors.",
			full = "Gallows' End Tavern is an inn located in Brill in the Tirisfal Glades. It features trainers for warriors, priests, mages, rogues, warlocks, enchanters, and first aid, in addition to the innkeeper and a few other vendors.\n\nA captured Scarlet Zealot and Dwarven Mountaineer are held in the cellars.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_End_Tavern",
		},
		["garrens haunt"] = {
			name = "Garren's Haunt",
			short = "Garren's Haunt is a large farmstead in the northern part of the Tirisfal Glades. It includes a farmhouse, a barn, a couple of silos, and a wide-stretched field.",
			full = "Garren's Haunt is a large farmstead in the northern part of the Tirisfal Glades. It includes a farmhouse, a barn, a couple of silos, and a wide-stretched field.\n\nThe darkhound Plague can be found in the barn.",
			source = "https://warcraft.wiki.gg/wiki/Garren's_Haunt",
