		["grand vestibule"] = {
			name = "Grand Vestibule",
			short = "The Grand Vestibule is the outermost chamber of the Scarlet Monastery. It holds the entrances to both the Scarlet Halls and Scarlet Monastery instances.",
			full = "The Grand Vestibule is the outermost chamber of the Scarlet Monastery. It holds the entrances to both the Scarlet Halls and Scarlet Monastery instances.\n\nThe vestibule itself is decorated with pillars and statues of scarlet warriors. It is often a contested place, as Horde and Alliance-affiliated adventurers mingle in the hall; with sometimes brutal results.",
			source = "https://warcraft.wiki.gg/wiki/Grand_Vestibule",
		},
		["grave prison of zakajz"] = {
			name = "Grave-Prison of Zakajz",
			short = "The Grave-Prison of Zakajz is a partially collapsed cavern where the C'Thrax known as Zakajz the Corruptor was imprisoned after his defeat against the titan keeper Tyr thousands of years ago.",
			full = "The Grave-Prison of Zakajz is a partially collapsed cavern where the C'Thrax known as Zakajz the Corruptor was imprisoned after his defeat against the titan keeper Tyr thousands of years ago. The cavern is housed under the Tomb of Tyr, connected by the Darkwalk.\n\nDuring the third invasion of the Burning Legion, a chosen warrior of Odyn was tasked to defeat Zakajz and obtain [Strom'kar, the Warbreaker] from his head. In the process, the chosen met the soul of Thoradin, who guided them to Zakajz and was able to leave this place and be at peace after the battle. The Conclave priests entered the tomb and the grave-prison where they fought Twilight Deacon Farthing who had [Xal'atath, Blade of the Black Empire]. In the end, the blade turned on Farthing and allowed itself to be claimed by the High Lord, followed by destroying the corpse of Zakajz. When Travard of the Tyr's Guard and the Highlord of the Order of the Silver Hand recovered a Spark of Tyr from the grave-prison, they retreated back to the Tomb of Tyr, chased by Mordoth the Hunter, where they freed [The Silver Hand], the prison collapsed with the tomb that lost its power source.",
			source = "https://warcraft.wiki.gg/wiki/Grave-Prison_of_Zakajz",
		},
		["gunthers retreat"] = {
			name = "Gunther's Retreat",
			short = "Gunther's Retreat is an island located in Brightwater Lake in central Tirisfal Glades. It is home to the Forsaken lich Gunther Arcanus and his zombie minions.",
			full = "Gunther's Retreat is an island located in Brightwater Lake in central Tirisfal Glades. It is home to the Forsaken lich Gunther Arcanus and his zombie minions. On the southwestern side of the retreat is a small, unnamed islet holding Lillith's Dinner Table.",
			source = "https://warcraft.wiki.gg/wiki/Gunther's_Retreat",
		},
		["night webs hollow"] = {
			name = "Night Web's Hollow",
			short = "Night Web's Hollow is a small valley and gold mine just northwest of Deathknell in Tirisfal Glades.",
			full = "Night Web's Hollow is a small valley and gold mine just northwest of Deathknell in Tirisfal Glades. Both the outdoors vale and the indoors mine are infested with spiders, which skitter among the shadows and lurk from their webbed corners. Young Forsaken usually test their mettle against the numerous spiders and sometimes venture deep into the mine to uncover its dusty secrets.\n\nOutside the mine, Young Night Web Spiders wander about. The mine itself houses many adult Night Web Spiders. In the deepest recesses of the mine, the Night Web Matriarch sits.",
			source = "https://warcraft.wiki.gg/wiki/Night_Web's_Hollow",
		},
		["nightmare vale"] = {
			name = "Nightmare Vale",
			short = "Nightmare Vale is a wide valley located just west of the Scarlet Watchtower in southwestern Tirisfal Glades.",
			full = "Nightmare Vale is a wide valley located just west of the Scarlet Watchtower in southwestern Tirisfal Glades. While the glades here were once verdant and teeming with forest animals, now the trees have withered and the wildlife has been eaten by hungry darkhounds and huge vampire bats. Ressan the Needler, a rare white bat, also appears here.",
			source = "https://warcraft.wiki.gg/wiki/Nightmare_Vale",
		},
		["north coast"] = {
			name = "North Coast",
			short = "The North Coast is a stretch of beach bordering a portion of the Great Sea. It lies along the northern edge of the Tirisfal Glades, and is mostly inhabited by ravenous murlocs and various marine animals.",
			full = "The North Coast is a stretch of beach bordering a portion of the Great Sea. It lies along the northern edge of the Tirisfal Glades, and is mostly inhabited by ravenous murlocs and various marine animals. Since the Plague of Undeath marred the region with its taint, the coast has become dark and cold, the site of several dead sea creatures rotting at the edge of the water.\n\nThe murloc Deeb can be found standing idle here.\n\nIn the Battle for Lordaeron, the coast became the landing site for the Alliance, destroying much of it -- including the murloc huts. The trail of destruction ranging from the Alliance's landfall to the ruins of Brill is called the Lion's Wake.",
			source = "https://warcraft.wiki.gg/wiki/North_Coast",
		},
		["rotbrain encampment"] = {
			name = "Rotbrain Encampment",
			short = "The Rotbrain Encampment is an area just outside Deathknell in the Forsaken starting zone inhabited by the Rotbrain Undead, those who have recently been resurrected but either are in denial, confused or wishing to exact vengeance.",
			full = "The Rotbrain Encampment is an area just outside Deathknell in the Forsaken starting zone inhabited by the Rotbrain Undead, those who have recently been resurrected but either are in denial, confused or wishing to exact vengeance. Led by Marcus Redpath, they are plotting an assault on the Forsaken.\n\nThe area is infested with Rotbrain Magi and Rotbrain Berserkers, locked in combat with Deathguard Protectors. Darnell will send players to deal with these recalcitrant undead and is promoted to a Deathguard for his efforts, though he does not actually help players fight.\n\nThe camp was ultimately attacked by Forsaken adventurers, leading to the destruction of the group.",
			source = "https://warcraft.wiki.gg/wiki/Rotbrain_Encampment",
		},
		["ruins of lordaeron"] = {
			name = "Ruins of Lordaeron",
			short = "The Ruins of Lordaeron (or Lordaeron Keep, also called Ruins of Capital City and Capital City Ruins, and sometimes referred to as Lordaeron City) is the remains of the city of Lordaeron, the great capital city of the fallen kingdom of Lordaeron.",
			full = "The Ruins of Lordaeron (or Lordaeron Keep, also called Ruins of Capital City and Capital City Ruins, and sometimes referred to as Lordaeron City) is the remains of the city of Lordaeron, the great capital city of the fallen kingdom of Lordaeron. It was destroyed by the Scourge after Arthas Menethil betrayed his people and set on the path to become the Lich King. The area is literally haunted by the final tragic events that led to the death of King Terenas and the city's destruction. Lordaeron's palace still stands, and once served as an entrance into the Forsaken capital of the Undercity.\n\nAfter the Battle for Lordaeron, the Forsaken lost control of the ruins, and the city was further devastated and completely blighted. With the help of adventurers, the Forsaken later applied techniques learned in Maldraxxus to purge the blight from the ruins. Afterward, the city became their new capital, watched over by the new Desolate Council. The city holds a translocation orb that links to Silvermoon City, and has also several portals that lead to Orgrimmar, Vengeance Landing, and Grom'gol Base Camp; in lieu of the still ruined zeppelin towers that once led to these locations.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
		["scarlet encampment"] = {
			name = "Scarlet Encampment",
			short = "The Scarlet Encampment is a small Scarlet Crusade camp located in the northern area of the Venomweb Vale in the Tirisfal Glades.",
			full = "The Scarlet Encampment is a small Scarlet Crusade camp located in the northern area of the Venomweb Vale in the Tirisfal Glades. This camp was under the command of Lieutenant Sanders, until Lilian Voss destroyed the camp and everyone within it.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Encampment",
		},
		["scarlet monastery"] = {
			name = "Scarlet Monastery",
			short = "The Scarlet Monastery, once known as the Old Monastery, is a fortified monastery located in the northeast corner of the blighted Tirisfal Glades, it was once a cathedral of the Church of the Holy Light, which was taken over by the Scarlet Crusade after the end of the Third War.",
			full = "The Scarlet Monastery, once known as the Old Monastery, is a fortified monastery located in the northeast corner of the blighted Tirisfal Glades, it was once a cathedral of the Church of the Holy Light, which was taken over by the Scarlet Crusade after the end of the Third War.\n\nAt the time of the third invasion of the Burning Legion, the remaining zealots of the Scarlet Crusade gathered at the monastery where they were massacred by the Knights of the Ebon Blade.\n\nThe Scarlet Monastery is a complex of two instanced dungeons, Scarlet Halls and Scarlet Monastery. Heroic mode is available for both wings at level 35.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Monastery",
		},
		["scarlet palisade"] = {
			name = "Scarlet Palisade",
			short = "The Scarlet Palisade is a Scarlet Crusade fortified camp located just west of the Solliden Farmstead in Tirisfal Glades.",
			full = "The Scarlet Palisade is a Scarlet Crusade fortified camp located just west of the Solliden Farmstead in Tirisfal Glades. It is from here the Scarlet Warriors protect the neighboring farm from any non-human that comes near. In the center of the camp is the Crusader's Outpost.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Palisade",
		},
		["scarlet watch post"] = {
			name = "Scarlet Watch Post",
			short = "The Scarlet Watch Post (or Crusader's Run) is a scout tower located in northeastern Tirisfal Glades, just north of the Scarlet Monastery.",
			full = "The Scarlet Watch Post (or Crusader's Run) is a scout tower located in northeastern Tirisfal Glades, just north of the Scarlet Monastery. Its maintenance despite its remote location is solely to prevent enemies of the Scarlet Crusade from assaulting the monastery from its less defensible north side. It's one of the four Crusader's Outpost towers in Tirisfal Glades. This particular tower is commanded by Captain Melrache.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Watch_Post",
		},
		["scarlet watchtower"] = {
			name = "Scarlet Watchtower",
			short = "The Scarlet Watchtower is a ruined scout tower located in southern Tirisfal Glades near the entrance to the Sewers of the Undercity.",
			full = "The Scarlet Watchtower is a ruined scout tower located in southern Tirisfal Glades near the entrance to the Sewers of the Undercity. It is under the control of the Scarlet Crusade, who use it to keep a watchful eye on flight routes coming to and from the Forsaken capital. It is one of four Crusader's Outpost towers in the Tirisfal Glades.\n\nThis particular tower is commanded by Captain Perrine.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Watchtower",
		},
		["sewers"] = {
			name = "Sewers",
			short = "The Sewers (or the bat sewer entrances) are a side entrance to the Undercity, accessible from west of the main gate to the Ruins of Lordaeron, near the Scarlet Watchtower in Tirisfal Glades.",
			full = "The Sewers (or the bat sewer entrances) are a side entrance to the Undercity, accessible from west of the main gate to the Ruins of Lordaeron, near the Scarlet Watchtower in Tirisfal Glades. This is used as the quickest way in and out for flight paths, as the only other way into the city is by using elevators from the ruins.\n\nThe sewers were used by the Alliance to enter the city during the Battle for the Undercity.\n\nYears later, the sewers were used by the Ebon Blade to enter the city during a mission to rescue Koltira Deathweaver.",
			source = "https://warcraft.wiki.gg/wiki/Sewers",
		},
		["shadow grave"] = {
			name = "Shadow Grave",
			short = "Shadow Grave is a crypt that lies at the top of a slope, within the Deathknell Graves, along the Tirisfal Glades mountains. A path runs down from Shadow Grave to Deathknell.",
			full = "Shadow Grave is a crypt that lies at the top of a slope, within the Deathknell Graves, along the Tirisfal Glades mountains. A path runs down from Shadow Grave to Deathknell.\n\nPlayers now awake in the nearby Deathknell Graves.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Grave",
		},
		["solliden farmstead"] = {
			name = "Solliden Farmstead",
			short = "The Solliden Farmstead is a human pumpkin farm in western Tirisfal Glades, just north of Deathknell and west of Calston Estate.",
			full = "The Solliden Farmstead is a human pumpkin farm in western Tirisfal Glades, just north of Deathknell and west of Calston Estate. One of the only places in northern Lordaeron where the native farmers have survived unaffected by the Plague of Undeath, its denizens are protected from the Forsaken and Scourge by the Scarlet Crusade at the nearby Scarlet Palisade. The farmers are hostile to both the Horde and the Alliance.\n\nArathorian settlers began establishing farmsteads in Tirisfal during Arathor's expansion circa 2,700 BDP. Circa 1,200 BDP, immigrant noble families from Strom bought up large plots of land developed by earlier settlers in Tirisfal, including the Solliden Farmstead.\n\nIn the current day, the Royal Apothecary Society sends adventurers to steal some of the farmstead's pumpkins for use in experiments with the New Plague. Deathguard Simmer sends adventurers to kill the humans themselves, out of a concern that the currently-peaceful farmers might be recruited by the Alliance in Gilneas or Stormwind and used against the Forsaken in the future.",
			source = "https://warcraft.wiki.gg/wiki/Solliden_Farmstead",
		},
		["stillwater pond"] = {
			name = "Stillwater Pond",
			short = "Stillwater Pond is a small lake located west of Brill in Tirisfal Glades.",
			full = "Stillwater Pond is a small lake located west of Brill in Tirisfal Glades. Before the Plague of Undeath, it was a popular site for picnics by the inhabitants of the glades, and the pond offered swimming opportunities for children who were not yet old enough to test their mettle in the much larger and deeper Brightwater Lake.\n\nNow the pond lies gray and forgotten, and only wandering undead and wild beasts set their eyes on its cold waters as they pass by. Only the still living skeletons of the lake's fish remain beneath the surface. The powerful darkhound Bayne roams around the pond, feasting on the unwary.\n\nA few new types of plant have begun to grow at Stillwater, with Marrowpetals growing at the bottom of the pond, and Stillwater Lilies growing around the edges. Furthermore, it has become infested with Giant Flesh-Eating Tadpoles thanks to irresponsible chemical disposal, courtesy of the Royal Apothecary Society.\n\nBy the time the Forsaken started rebuilding Brill, Scarlet Warriors were patroling around Stillwater Pond.",
			source = "https://warcraft.wiki.gg/wiki/Stillwater_Pond",
		},
		["terrace of repose"] = {
			name = "Terrace of Repose",
			short = "The Terrace of Repose is located on the grounds just north of the Scarlet Monastery entrance.",
			full = "The Terrace of Repose is located on the grounds just north of the Scarlet Monastery entrance. It is one of the very few places in northern Lordaeron where the Plague of Undeath has not reached, and the Scarlet Crusade have been able to grow green hedges and maintain a fountain with water that is fresh rather than stagnant like the rest of Tirisfal Glades.",
			source = "https://warcraft.wiki.gg/wiki/Terrace_of_Repose",
		},
		["tomb of tyr"] = {
			name = "Tomb of Tyr",
			short = "The Tomb of Tyr (or Keeper's Rest) is an underground area located under the lake of Tyr's Fall in the Whispering Forest in western Tirisfal Glades.",
			full = "The Tomb of Tyr (or Keeper's Rest) is an underground area located under the lake of Tyr's Fall in the Whispering Forest in western Tirisfal Glades. It is accessible from a narrow entrance at the bottom of the lake. The area is comprised of the Vestibule of the Silver Hand, Tyr's tomb proper, the Darkwalk, and the Grave-Prison of Zakajz.",
			source = "https://warcraft.wiki.gg/wiki/Tomb_of_Tyr",
		},
		["tyrs fall"] = {
			name = "Tyr's Fall",
			short = "Tyr's Fall (or Tirisfal in the vrykul tongue) is a craterous lake found within the Whispering Forest in western Tirisfal Glades, for which it is the namesake.",
			full = "Tyr's Fall (or Tirisfal in the vrykul tongue) is a craterous lake found within the Whispering Forest in western Tirisfal Glades, for which it is the namesake. As the name suggests, it was the place where the titan keeper Tyr made his final stand against the C'Thrax generals Zakajz and Kith'ix. Under the lake lies a tomb, the final resting place of Tyr, which collapsed.\n\nThe tomb and the surrounding area have been guarded by a secretive group of paladins known as the Tyr's Guard for thousands of years.",
			source = "https://warcraft.wiki.gg/wiki/Tyr's_Fall",
		},
		["undercity"] = {
			name = "Undercity",
			short = "The Undercity, now known as the Ruins of Undercity, was the capital city of the Forsaken kingdom, located beneath the ruins of Capital City in Tirisfal Glades.",
			full = "The Undercity, now known as the Ruins of Undercity, was the capital city of the Forsaken kingdom, located beneath the ruins of Capital City in Tirisfal Glades. Originally intended by Arthas Menethil to be the Scourge's seat of power in Lordaeron, the budding \"Undercity\" was abandoned when the death knight was recalled by the Lich King in the distant Northrend. During the Plaguelands civil war, Sylvanas Windrunner and the Forsaken rebels claimed the Undercity for their own, then spent years completing the twisted maze of catacombs the Scourge had begun constructing. It was much more defensible than the city above it.\n\nPlagued by the Banshee Queen during the Battle for Lordaeron, its surface has since been cleansed by the efforts of the Desolate Council.",
			source = "https://warcraft.wiki.gg/wiki/Undercity",
		},
		["underwater passage"] = {
			name = "Underwater Passage",
			short = "The Underwater Passage is a sub-aquatic tunnel in western Tirisfal Glades that leads from the lake of Tyr's Fall in the Whispering Forest to the Tomb of Tyr beneath the lake's floor.",
			full = "The Underwater Passage is a sub-aquatic tunnel in western Tirisfal Glades that leads from the lake of Tyr's Fall in the Whispering Forest to the Tomb of Tyr beneath the lake's floor.",
			source = "https://warcraft.wiki.gg/wiki/Underwater_Passage",
		},
		["venomweb vale"] = {
			name = "Venomweb Vale",
			short = "Venomweb Vale is a wide valley located in eastern Tirisfal Glades, just south of the Scarlet Monastery.",
			full = "Venomweb Vale is a wide valley located in eastern Tirisfal Glades, just south of the Scarlet Monastery. While the vale used to be a haven for hunting deer and rabbits, its trees verdant and the grass green, it is now a tainted place full of poisonous and deadly spiders led by Sri'skulk which give the vale its new name.\n\nIn the northern part of the valley, darkhounds roam near the Scarlet Encampment, a Scarlet Crusade camp under the command of Lieutenant Sanders.",
			source = "https://warcraft.wiki.gg/wiki/Venomweb_Vale",
		},
		["vestibule of the silver hand"] = {
			name = "Vestibule of the Silver Hand",
			short = "The Vestibule of the Silver Hand is the proper entrance to the Tomb of Tyr found after swimming through the Underwater Passage.",
			full = "The Vestibule of the Silver Hand is the proper entrance to the Tomb of Tyr found after swimming through the Underwater Passage.\n\nThey found Travard in the vestibule, frustrated at being locked out by the tomb's defense systems. The old paladin decided to aid them as they entered the Tomb of Tyr, hoping that they contained enough memories to activate the [Silver Scale] in order to revive Tyr's new body.",
			source = "https://warcraft.wiki.gg/wiki/Vestibule_of_the_Silver_Hand",
		},
		["whispering forest"] = {
			name = "Whispering Forest",
			short = "The Whispering Forest is a large forest located within the mountains of western Tirisfal Glades, just west of Deathknell and south of Tyr's Fall.",
			full = "The Whispering Forest is a large forest located within the mountains of western Tirisfal Glades, just west of Deathknell and south of Tyr's Fall. It is accessible via flight or by druids with Glyph of One With Nature. The forest contains families of diseased stags, does and fawns, rats and one diseased bear.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Forest",
		},
		["whispering gardens"] = {
			name = "Whispering Gardens",
			short = "The Whispering Gardens are located in northeastern Tirisfal Glades, on the hill south of Scarlet Monastery entrance. A great battle was fought here between, what would become, the Scarlet Crusade and a host of Scourge.",
			full = "The Whispering Gardens are located in northeastern Tirisfal Glades, on the hill south of Scarlet Monastery entrance. A great battle was fought here between, what would become, the Scarlet Crusade and a host of Scourge. The spirits of those fallen in battle can still be heard here as faint whispers in the twilight.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Gardens",
		},
		["whispering shore"] = {
			name = "Whispering Shore",
			short = "The Whispering Shore is a small stretch of coast located in western Tirisfal Glades, just north of the Solliden Farmstead.",
			full = "The Whispering Shore is a small stretch of coast located in western Tirisfal Glades, just north of the Solliden Farmstead. While this area used to be a popular spot for fishing, it is now the site of a band of murlocs ravenously attacking anyone who wanders near. The water off the coast is cold and dark, and nothing remains of its former bounty. The fierce murloc Muad is the leader of the invaders.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Shore",
		},
	},
	-- Silverpine Forest: 33 subzones
	[1421] = {
		["7th legion base camp"] = {
			name = "7th Legion Base Camp",
			short = "7th Legion Base Camp is a dwarven base of operations in Silverpine Forest, headed by General Marstone. Dwarven Infantry patrol the area.",
			full = "7th Legion Base Camp is a dwarven base of operations in Silverpine Forest, headed by General Marstone. Dwarven Infantry patrol the area.\n\nLord Godfrey will have Horde heroes come here to assassinate Marstone in the quest [5-30] Sowing Discord in order to slow the advance of the Alliance forces in the resultant confusion. Meanwhile Lord Walden wants some recon data in [5-30] 7th Legion Battle Plans. Heroes wandering into the area should be advised that the mobs are elites due to the presence of three friendly NPCs during the associated quests.",
			source = "https://warcraft.wiki.gg/wiki/7th_Legion_Base_Camp",
		},
		["ambermill"] = {
			name = "Ambermill",
			short = "Ambermill (or Amber Mill) was a human town located slightly southwest of Lordamere Lake in Silverpine Forest. It is made up of a town hall, a stables, several mills, and a lumber mill.",
			full = "Ambermill (or Amber Mill) was a human town located slightly southwest of Lordamere Lake in Silverpine Forest. It is made up of a town hall, a stables, several mills, and a lumber mill. It was originally part of kingdom of Gilneas. Following the Third War, the town was occupied by the forces of the Kirin Tor from the Magocracy of Dalaran, who were friendly with the Alliance. However, the town was eventually conquered by the Forsaken at the time of the invasion of Gilneas. Following the final battle of the Silverpine Forest campaign, the area is inhabited by servitors once more, though the shield is gone.",
			source = "https://warcraft.wiki.gg/wiki/Ambermill",
		},
		["battlefront"] = {
			name = "Battlefront",
			short = "The Battlefront is large region of Silverpine Forest between Shadowfang Keep and the Greymane Wall.",
			full = "The Battlefront is large region of Silverpine Forest between Shadowfang Keep and the Greymane Wall. It is currently inhabited by both Forsaken Horde forces, and the 7th Legion and Gilneas Liberation Front of the Alliance. Additionally, Marsh Crocolisks have eaten one of Lord Godfrey's friends here and will drop an item that begins a quest.\n\nThe main Horde camp is the Forsaken Front, where Sylvanas Windrunner leads the war preparations that culminate in a final showdown in [5-30] Cities in Dust. Alliance encampments include the 7th Legion Base Camp, where the dwarves under General Marstone are located, and the Gilneas Liberation Front Base Camp, where Lorna Crowley can be found. The once isolated Pyrewood Village has become ground zero for the conflict between these two sides.",
			source = "https://warcraft.wiki.gg/wiki/Battlefront",
		},
		["berens peril"] = {
			name = "Beren's Peril",
			short = "Beren's Peril is located in Silverpine Forest due southwest of Ambermill, between the main road and the side road coming from Ambermill in the hills.",
			full = "Beren's Peril is located in Silverpine Forest due southwest of Ambermill, between the main road and the side road coming from Ambermill in the hills. The path leading up to it starts at .",
			source = "https://warcraft.wiki.gg/wiki/Beren's_Peril",
		},
		["dawning isles"] = {
			name = "Dawning Isles",
			short = "The Dawning Isles used to be an idyllic set of low keys that rose from the crystalline surface of Lordamere Lake, but had been affected by the Plague of Undeath.",
			full = "The Dawning Isles used to be an idyllic set of low keys that rose from the crystalline surface of Lordamere Lake, but had been affected by the Plague of Undeath. The trees grew sickly, and dangerous murlocs and bog beasts roamed the islets. The bog beasts have since vanished and the Vile Fin murlocs are grown to a very large population taking control of the isles.\n\nThe isles were taken over by the Scarlet Crusade. They mounted an attack on the Ruins of Lordaeron, and the Forsaken tried to counterattack.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Isles",
		},
		["dead field"] = {
			name = "Dead Field",
			short = "The Dead Field was the name of a decrepit and abandoned farm in northern Silverpine Forest. The nature and number of the farm's former inhabitants were unknown.",
			full = "The Dead Field was the name of a decrepit and abandoned farm in northern Silverpine Forest. The nature and number of the farm's former inhabitants were unknown. The Dead Field became a base for the Rot Hide gnolls, servants of the Scourge. It is unknown what the Scourge planned are for the farm, but the increasing number of gnolls suggested imminent military action.\n\nA reconnaissance mission undertaken by the Deathstalkers passed through the field on their mission through northern Silverpine, noting the presence of the Scourge at the farm. Repeated small assaults by the Forsaken upon the Dead Field have been unsuccessful because of the arrival of a banshee known as Nightlash. The banshee appears when the Rot Hides under her command are attacked.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Field",
		},
		["decrepit ferry"] = {
			name = "Decrepit Ferry",
			short = "The Decrepit Ferry used to be the location of a bustling ferry service that transported goods and people to and from Fenris Isle.",
			full = "The Decrepit Ferry used to be the location of a bustling ferry service that transported goods and people to and from Fenris Isle. The nearby farmsteads all sold part of their crops to the island's rich lord and his family, and the ferryman was paid a small fee for each trip.\n\nThen the Scourge invaded Lordaeron. The ferryman was brutally murdered, the ferry was destroyed, and ghouls, skeletal warriors, and Rot Hide gnolls invaded the docks. It is now a hazardous place to venture for inexperienced travelers.",
			source = "https://warcraft.wiki.gg/wiki/Decrepit_Ferry",
		},
		["decrepit fields"] = {
			name = "Decrepit Fields",
			short = "The Decrepit Fields, formerly the Decrepit Ferry, is an area in Silverpine Forest located between the Sepulcher and Fenris Isle, on the shore of Lordamere Lake.",
			full = "The Decrepit Fields, formerly the Decrepit Ferry, is an area in Silverpine Forest located between the Sepulcher and Fenris Isle, on the shore of Lordamere Lake. It has become home to a large number of Hillsbrad Worgen who chose to seek vengeance against the Forsaken rather than be raised into undeath. A number of ruined Forsaken catapults are located here.\n\nWarlord Torok made the mistake of sending his Orc Sea Dogs to fight the Hillsbrad forces without providing them with adequate alcohol. They now lie unconscious on the ground. He will send players to wake them up while Sylvanas has you deal with the worgen.\n\nAt the end of the fields along the shoreline exists a pier that once had a ferry filled with corpses. The pier now has a Horde Communication Panel and three Horde Cannons on it, along with Killian Sanatha whom apparently was of no interest to the waves of newly transformed worgen refugees, as he still stands on the pier fishing, unmolested. Fenwick Thatros, a rare spawn, can be found here as well.\n\nWhen the Scarlet Crusade took over Fenris Isle and attacked the Ruins of Lordaeron, the Decrepit Fields was empty of the orc and worgen forces, and instead it was inhabited by Giant Rabid Bears and Rabid Worgs. The dock was taken over by Scarlet Recruits, with Killian relocating to the Sepulcher.",
			source = "https://warcraft.wiki.gg/wiki/Decrepit_Fields",
		},
		["deep elem mine"] = {
			name = "Deep Elem Mine",
			short = "The Deep Elem Mine is a mine in the middle of Silverpine Forest.",
			full = "The Deep Elem Mine is a mine in the middle of Silverpine Forest.",
			source = "https://warcraft.wiki.gg/wiki/Deep_Elem_Mine",
		},
		["fenris isle"] = {
			name = "Fenris Isle",
			short = "Fenris Isle is a large island located in the center of Lordamere Lake and it is generally considered to be a part of Silverpine Forest.",
			full = "Fenris Isle is a large island located in the center of Lordamere Lake and it is generally considered to be a part of Silverpine Forest. Together with the Dawning Isles, they form a broken circle of dry land in the lake.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Isle",
		},
		["fenris keep"] = {
			name = "Fenris Keep",
			short = "The gloomy Fenris Keep lays at the center of Lordamere Lake in Silverpine Forest upon the Fenris Isle. The keep had strategic significance, and was home to a sizable portion of Lordaeron's military.",
			full = "The gloomy Fenris Keep lays at the center of Lordamere Lake in Silverpine Forest upon the Fenris Isle. The keep had strategic significance, and was home to a sizable portion of Lordaeron's military.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Keep",
		},
		["forsaken front"] = {
			name = "Forsaken Front",
			short = "The Forsaken Front is an outpost and front lines to the Battlefront in southern Silverpine Forest.",
			full = "The Forsaken Front is an outpost and front lines to the Battlefront in southern Silverpine Forest. It's here Lady Sylvanas commands the attack on the Gilneas Liberation Front and where she had Lord Godfrey, Walden, and Baron Ashbury raised into her service.",
			source = "https://warcraft.wiki.gg/wiki/Forsaken_Front",
		},
		["forsaken high command"] = {
			name = "Forsaken High Command",
			short = "Forsaken High Command, part of the Forsaken Front, is a subzone of Silverpine Forest and is the first quest hub players will run across after their adventures in Tirisfal Glades.",
			full = "Forsaken High Command, part of the Forsaken Front, is a subzone of Silverpine Forest and is the first quest hub players will run across after their adventures in Tirisfal Glades.\n\nYou will need to complete this in order to make the flightmaster and other vendors appear.\n\nOn the way here from Tirisfal Glades, players will witness Dreadguards marching up and down the zone as well as pass by Forsaken Troopers and Forsaken Apothecaries preparing for battle with Gilneas.",
			source = "https://warcraft.wiki.gg/wiki/Forsaken_High_Command",
		},
		["forsaken rear guard"] = {
			name = "Forsaken Rear Guard",
			short = "Forsaken Rear Guard is a Forsaken base located between Forsaken High Command and the Sepulcher in Silverpine Forest.",
			full = "Forsaken Rear Guard is a Forsaken base located between Forsaken High Command and the Sepulcher in Silverpine Forest. A large contingent of Orgrimmar sea forces has recently arrived here, and they appear to enjoy their alcohol. Orc Sea Dogs can be found throughout the area.",
			source = "https://warcraft.wiki.gg/wiki/Forsaken_Rear_Guard",
		},
		["gilneas liberation front base camp"] = {
			name = "Gilneas Liberation Front Base Camp",
			short = "Gilneas Liberation Front Base Camp is a worgen base of operations in Silverpine Forest, headed by Commander Lorna Crowley and inhabited by Worgen Warbringers.",
			full = "Gilneas Liberation Front Base Camp is a worgen base of operations in Silverpine Forest, headed by Commander Lorna Crowley and inhabited by Worgen Warbringers.\n\nLord Godfrey will have Horde heroes come here to kidnap Crowley during an assignment. Heroes wandering into the area should be advised that the mobs are elites due to the presence of three friendly during the associated quests.",
			source = "https://warcraft.wiki.gg/wiki/Gilneas_Liberation_Front_Base_Camp",
		},
		["greymane wall"] = {
			name = "Greymane Wall",
			short = "The Greymane Wall was erected before the Third War by order of King Genn Greymane, as the kingdom of Gilneas isolated itself from the Alliance of Lordaeron and the rest of the world due to a disagreement surrounding the maintenance taxes about the internment camps for the orcs, and other political disputes.",
			full = "The Greymane Wall was erected before the Third War by order of King Genn Greymane, as the kingdom of Gilneas isolated itself from the Alliance of Lordaeron and the rest of the world due to a disagreement surrounding the maintenance taxes about the internment camps for the orcs, and other political disputes. It is a colossal wall with a substantially sized gate, located at the southern edge of the Silverpine Forest in Lordaeron (its entrance near Pyrewood Village) and the northern edge of the Gilnean peninsula.\n\nThe controversial edifice led to the rise of tensions among the people of Gilneas, but protected them from the Plague of Undeath and the Scourging of Lordaeron. During the war across the continent, many refugees that escaped the undead made camp outside of the wall, but its gates remained closed for years, and the refugees perished at some point.\n\nFollowing the end of the Third War, the wall sowed civil discord in the isolated kingdom, rising until eventually led to the Northgate Rebellion, a devastating civil war that nearly destroyed the nation. Though King Greymane was able to put down the dissenters with the apprehension of the rebellion's leader, Lord Darius Crowley, the kingdom began to experience other troubles, in the form of the worgen curse.",
			source = "https://warcraft.wiki.gg/wiki/Greymane_Wall",
		},
		["ivar patch"] = {
			name = "Ivar Patch",
			short = "The Ivar Patch is a pumpkin patch in northern Silverpine Forest. This was once a prosperous and pleasant farm, and Ivar employed many farmhands and servants.",
			full = "The Ivar Patch is a pumpkin patch in northern Silverpine Forest. This was once a prosperous and pleasant farm, and Ivar employed many farmhands and servants. That was only until the Scourge ravaged the lands of Lordaeron, however.",
			source = "https://warcraft.wiki.gg/wiki/Ivar_Patch",
		},
		["lordamere lake"] = {
			name = "Lordamere Lake",
			short = "Lordamere Lake (or Lake Lordamere) is one of the largest lakes in the Eastern Kingdoms, rivaled only by Darrowmere Lake to the east.",
			full = "Lordamere Lake (or Lake Lordamere) is one of the largest lakes in the Eastern Kingdoms, rivaled only by Darrowmere Lake to the east. Along with Darrowmere, this lake has been marked by many events that took place around it. Here, many human kingdoms, at the age of the Alliance of Lordaeron, that were prosperous, have been found around the lake's shores and nearby mountains, including Lordaeron, Dalaran and Alterac. Lordamere was very likely given its name from the nearby Capital City of the kingdom of Lordaeron which was built on its northern shores and which was named after Lordain.\n\nSome time after the Third War, Lady Vashj and her naga retreated here after the battle at the ruins of Dalaran.\n\nThe lake, for a time, acted as a natural barrier between the Forsaken lands of Tirisfal Glades and Silverpine Forest and the contested lands of the Alterac Mountains. At its center lie the Dawning Isles, and Fenris Isle which was taken over by agents of the Scourge, who were being attacked by the Forsaken. However, they were ultimately removed by the worgen. Fenris Isle was later taken by Hillsbrad Refugees and the leaders of Southshore, having escaped from the Hillsbrad Foothills, as a temporary safe haven from the Forsaken. East of Fenris Isle, the small group of islands called the Dawning Isles are where the Vile Fin murlocs have made their claim overrunning them.\n\nAt some point, Fenris Isle, namely its keep, was overtaken by the Forsaken led by Deathstalker Hayward. The Horde later distracted these forces to evacuate Undercity refugees across the lake.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Lake",
		},
		["maldens orchard"] = {
			name = "Malden's Orchard",
			short = "Malden's Orchard is a small orchard in northern Silverpine Forest. The trees in the orchard are dark and evergreen, but their fruits have not been picked in years.",
			full = "Malden's Orchard is a small orchard in northern Silverpine Forest. The trees in the orchard are dark and evergreen, but their fruits have not been picked in years. The orchard is named for its former owner, who was forced to flee his home when the Scourge invaded Lordaeron.\n\nRecently, large numbers of black worgs have taken up residence around the orchard and its single small cottage. When the Deathstalkers Rane Yorick, Quinn Yorick, and Erland McKree were conducting their reconnaissance mission, Erland was tasked with exploring Malden's Orchard. When he arrived, he encountered the numerous worgs and was forced to take refuge within the abandoned cottage. He was pinned down for several days until with the aid of Forsaken agents, he managed to make his escape and flee back to his partners at the Ivar Patch to the southwest.",
			source = "https://warcraft.wiki.gg/wiki/Malden's_Orchard",
		},
		["north tides beachhead"] = {
			name = "North Tide's Beachhead",
			short = "North Tide's Beachhead is the shore in northwestern Silverpine Forest currently under the control of Bloodfang worgen.",
			full = "North Tide's Beachhead is the shore in northwestern Silverpine Forest currently under the control of Bloodfang worgen. This is the location where two of the three Horde ships filled with reinforcements and a drunken crew built a small camp before being defeated by the feral worgen.\n\nThe third ship sank just north of here at the Skittering Dark.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Beachhead",
		},
		["north tides hollow"] = {
			name = "North Tide's Hollow",
			short = "North Tide's Hollow was a region of Silverpine Forest just north of the Sepulcher. The Hollow was one of the many haunts of the evil Moonrage worgen, the servants of the Archmage Arugal.",
			full = "North Tide's Hollow was a region of Silverpine Forest just north of the Sepulcher. The Hollow was one of the many haunts of the evil Moonrage worgen, the servants of the Archmage Arugal. These worgen set up very crude encampments in some places. These camps employed only the meanest necessities of survival needed by the tough worgen.\n\nWhile the subzone has been removed, the camp still exists, but as part of the North Tide's Beachhead.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Hollow",
		},
		["north tides run"] = {
			name = "North Tide's Run",
			short = "North Tide's Run is the name given to the northwestern shoreline of Silverpine Forest. The region includes the beach and a thin strip of the Great Sea.",
			full = "North Tide's Run is the name given to the northwestern shoreline of Silverpine Forest. The region includes the beach and a thin strip of the Great Sea. The most prominent feature of the run is the partially submerged ship that lies at the edge of the water.\n\nWallace the Blind has setup a small campfire near the waters by the sunken Horde ship.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Run",
		},
		["olsens farthing"] = {
			name = "Olsen's Farthing",
			short = "Olsen's Farthing was once a bustling farmstead with direct contact into the main throughway of trade in the Silverpine Forest.",
			full = "Olsen's Farthing was once a bustling farmstead with direct contact into the main throughway of trade in the Silverpine Forest.\n\nThis section concerns content related to the original World of Warcraft.\n\nA few years after the Third War, the Olsen's Farthing was left in ruins, with undead under the control of Thule Ravenclaw ravenously attacking anyone in the area.\n\nDuring the invasion of Gilneas, Bloodfang Stalkers prowled around the area, while the corpses of Veteran Forsaken Troopers littered the ground. Caretaker Smithers relocated here from Hillsbrad, while Lady Sylvanas Windrunner sent Horde adventurers there to avenge the Forsaken forces and search for clues as to the recent dealings of Darius Crowley and Ivar Bloodfang. The fields are also much bigger.\n\nYears later, by the time the Scarlet Crusade took control of Fenris Isle, several plagued wolves, bears, and sickly deer were present on the farm. The crusaders also left propaganda against the Forsaken on the trees. Velonara and Faranell sent adventurers to the farm to kill the beasts for their flesh, collect [Boom Weed], and to destroy the propaganda.",
			source = "https://warcraft.wiki.gg/wiki/Olsen's_Farthing",
		},
