		["pyrewood village"] = {
			name = "Pyrewood Village",
			short = "Pyrewood Village (or simply Pyrewood) was an Alliance-friendly Gilnean village within the Silverpine Forest.",
			full = "Pyrewood Village (or simply Pyrewood) was an Alliance-friendly Gilnean village within the Silverpine Forest. The village was a settlement, with a town hall, a blacksmith, and a chapel, inhabited by a group of humans who had survived the coming of the Scourge during the Third War. However, they were later cursed by the maddened Arugal, who turned the townsfolk into rampaging worgen at night.\n\nIt was finally being burned down by agents of the Horde on the orders of Lord Vincent Godfrey.",
			source = "https://warcraft.wiki.gg/wiki/Pyrewood_Village",
		},
		["sepulcher"] = {
			name = "Sepulcher",
			short = "The Sepulcher, also known as the Silverpine Sepulcher, is a Forsaken base located in the western side of Silverpine Forest. The area itself lies above the Lordaeronian coastline, nestled within the surrounding hills.",
			full = "The Sepulcher, also known as the Silverpine Sepulcher, is a Forsaken base located in the western side of Silverpine Forest. The area itself lies above the Lordaeronian coastline, nestled within the surrounding hills. It was nothing more than a large graveyard and string of expeditionary caravans and individuals.",
			source = "https://warcraft.wiki.gg/wiki/Sepulcher",
		},
		["shadowfang keep"] = {
			name = "Shadowfang Keep",
			short = "Shadowfang Keep is a haunted keep not far from the borders of Gilneas in southern Silverpine Forest, on a high bluff overlooking Pyrewood Village.",
			full = "Shadowfang Keep is a haunted keep not far from the borders of Gilneas in southern Silverpine Forest, on a high bluff overlooking Pyrewood Village. It was named for the forces of its former master, the demented Archmage Arugal, who wrested the keep from Baron Silverlaine with his worgen \"children\" and held it until he was defeated by a group of Horde heroes. The keep was then occupied by the Scourge remnants and followers of the renegade Gilnean nobleman Vincent Godfrey, traitor to both his homeland and to the Forsaken who returned him from death.\n\nBy the end of the war, the Bloodfang pack had taken control of the keep, moving most of its artifacts to Fenris Keep to be guarded closely.",
			source = "https://warcraft.wiki.gg/wiki/Shadowfang_Keep",
		},
		["shining strand"] = {
			name = "Shining Strand",
			short = "The Shining Strand is the name of the section of shoreline of Lordamere Lake in Silverpine Forest.",
			full = "The Shining Strand is the name of the section of shoreline of Lordamere Lake in Silverpine Forest. It stretches from the Lordaeron capital city in the north and ends at the range of rough hills that divides Silverpine from the Alterac Mountains.\n\nThe Vile Fin tribe of murlocs used to have several settlements along the strand making it very dangerous for unseasoned travelers, until they moved to the Dawning Isles. In his journal, the late Apothecary Berard spoke of a rare item that could be obtained from the Vile Fins, a Hardened Tumor. Berard speculated that the tumor could be used in the concoction of a new plague.\n\nThe Forsaken, likely having forced the murlocs out, have setup several camps along the shoreline and are currently fighting with worgen.",
			source = "https://warcraft.wiki.gg/wiki/Shining_Strand",
		},
		["skittering dark"] = {
			name = "Skittering Dark",
			short = "The Skittering Dark is an abandoned mine and nearby area crawling with Skitterweb spiders found just west of the Forsaken Rear Guard and east of North Tide's Run in Silverpine Forest.",
			full = "The Skittering Dark is an abandoned mine and nearby area crawling with Skitterweb spiders found just west of the Forsaken Rear Guard and east of North Tide's Run in Silverpine Forest.\n\nThe spiders here are led by the Skitterweb Matriarch, a gigantic spider hiding deep within the mine. Krethis the Shadowspinner, a rare spider, can sometimes be found outside the mine. Several cocoons litter the area filled with worgen, worgs, bears, and even the orcs that crashed along the shore to the west.",
			source = "https://warcraft.wiki.gg/wiki/Skittering_Dark",
		},
		["south tides run"] = {
			name = "South Tide's Run",
			short = "South Tide's Run is complementary to North Tide's Run, and is the name for the southwestern coast of Silverpine Forest bordering the Great Sea.",
			full = "South Tide's Run is complementary to North Tide's Run, and is the name for the southwestern coast of Silverpine Forest bordering the Great Sea.",
			source = "https://warcraft.wiki.gg/wiki/South_Tide's_Run",
		},
		["valgans field"] = {
			name = "Valgan's Field",
			short = "Valgan's Field is yet another among the desolate farms of northern Silverpine Forest. This farm is located just west of the Shining Strand, east of the main north-south road, and north of a small river.",
			full = "Valgan's Field is yet another among the desolate farms of northern Silverpine Forest. This farm is located just west of the Shining Strand, east of the main north-south road, and north of a small river. It is named after its former owner, who was either killed or forced to flee from his farm when the Scourge arrived in Silverpine. Formerly occupied by the feral Moonrage worgen, they have since vanished, leaving the farm empty. Only Nightlash can occasionally be spotted around here. At its heyday, the farm would have been a lovely place, offering a magnificent view of Lordamere Lake.\n\nCommanded by Lieutenant Hawlsey, it was used as a training ground. The Forsaken leadership sent adventurers to kill Hawlsey and his recruits.",
			source = "https://warcraft.wiki.gg/wiki/Valgan's_Field",
		},
	},
